class DoWhileStatement extends Statement {
    private Statement body;
    private Expression condition;

    public DoWhileStatement(Statement body, Expression condition) {
        this.body = body;
        this.condition = condition;
    }

    public void translate(BufferedWriter out) throws IOException {
        String startLab = ASTNode.genLab();
        String endLab = ASTNode.genLab();

        out.write(startLab + ":");
        out.newLine();
        body.translate(out);
        out.write("\tJump\t" + endLab);
        out.newLine();

        out.write(endLab + ":");
        out.newLine();
        condition.translate(out);
        condition.genLoad("R1", out);
        out.write("\tJumpIfZero\tR1, " + startLab);
        out.newLine();
    }
}

